SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',(to_jsonb(c)-ARRAY['relfilenode','relpages','reltuples','relallvisible','relfrozenxid','relminmxid']),'identity',to_jsonb(pg_identify_object('pg_class'::regclass,c.oid,0)),'owner',pg_get_userbyid(c.relowner),'definition',pg_get_viewdef(c.oid,false),'options',c.reloptions,'ACL',c.relacl) ORDER BY c.oid),'[]'::jsonb) AS payload FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relkind IN ('v','m')) AS capture